/** UPU S10 check digit weights for the 8 serial digits (see docs/carriers.md). */
const WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** Computes the S10 check digit for 8 serial digits. */
export function s10CheckDigit(serial: string): number {
  let sum = 0;
  for (let i = 0; i < WEIGHTS.length; i++) sum += Number(serial[i]) * WEIGHTS[i]!;
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

const ATP_FORMAT = /^[A-Z]{2}(\d{8})(\d)AT$/;

export type AtpTrackingCheck = 'ok' | 'bad_format' | 'bad_check_digit';

/** Checks an Austrian Post tracking number (S10, country code AT). Expects upper case input. */
export function checkAtpTrackingNumber(trackingNumber: string): AtpTrackingCheck {
  const match = ATP_FORMAT.exec(trackingNumber);
  if (!match) return 'bad_format';
  return s10CheckDigit(match[1]!) === Number(match[2]) ? 'ok' : 'bad_check_digit';
}
